const useCartStore = create((set) => ({
  items: [],
  promo: null,
  shipping: "standard",
}));

function BadgeA() {
  const count = useCartStore((s) => s.items.length);
  return <span>{count}</span>;
}

function BadgeB() {
  const view = useCartStore((s) => ({ count: s.items.length, shipping: s.shipping }));
  return <span>{view.count} / {view.shipping}</span>;
}

// Write: useCartStore.setState({ promo: "SAVE10" })

