function useStore(store) {
  const [value, setValue] = useState(store.get());
  useEffect(() => store.subscribe(() => setValue(store.get())), [store]);
  return value;
}

Симптом: шапка читает стор в начале длинного прохода рендера; тик цены
мутирует стор посреди рендера; строки читают новое значение после возобновления.
Один закоммиченный кадр содержит две версии стора — это называется ___b1___.
Это стало возможным, потому что transitions делают рендеринг ___b2___, и проход
рендера может растянуться поверх записи в стор. Лечение — заменить самописный хук
на ___b3___, который перепроверяет снапшот и принуждает к синхронному ре-рендеру
при конфликте.

